import functools

def log_calls(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def log_calls_fixed(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@log_calls
def fetch_user(user_id):
    """Look up a user by id."""
    return {"id": user_id}

@log_calls_fixed
def fetch_order(order_id):
    """Look up an order by id."""
    return {"id": order_id}

print(fetch_user.__name__, "|", fetch_user.__doc__)
print(fetch_order.__name__, "|", fetch_order.__doc__)
# wrapper | None
# fetch_order | Look up an order by id.

import functools
import time

def timed(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f"{func.__name__} took {elapsed:.4f}s")
        return result
    return wrapper

@timed
def slow_sum(n):
    return sum(range(n))

@timed
def greet(name, greeting="Hello"):
    return f"{greeting}, {name}!"

slow_sum(5_000_000)
print(greet("Amy", greeting="Hi"))
# slow_sum took 0.1502s
# Hi, Amy!
# greet took 0.0000s

